begin;
create function pg_temp.expect(value boolean,description text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',description;end if;end$$;
create function pg_temp.rejects(statement text) returns boolean language plpgsql as $$begin execute statement;return false;exception when others then return true;end$$;
grant execute on function pg_temp.expect(boolean,text),pg_temp.rejects(text) to authenticated;
do $$
declare h uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); s uuid:=gen_random_uuid();
 hs uuid:=gen_random_uuid(); cs uuid:=gen_random_uuid(); ss uuid:=gen_random_uuid();
 hid text:='experience-check-'||h; cid text:='experience-check-'||c; sid text:='experience-check-'||s;
 aid uuid:=gen_random_uuid(); review_session uuid:=gen_random_uuid(); photo_id uuid:=gen_random_uuid(); rev integer; receipt jsonb;
 body jsonb:='{"title":"Campus orientation walk","category":"culture_tours","what_to_expect":"We walk through the local campus area and explain the history, meeting places and practical orientation information.","host_expertise":"I have led orientation walks locally and can explain the planned route and its landmarks.","country_code":"NG","state":"Nasarawa","local_area":"Lafia","city":"Lafia","meeting_area":"Agreed public meeting point","timezone":"Africa/Lagos","participation_requirements":"Adults able to walk this route; comfortable shoes required.","accessibility_information":"Step-free route; contact the host for assistance arrangements.","duration_minutes":60,"max_group_size":8,"inclusions":["Guided walk"],"exclusions":["Transport"]}';
begin
 insert into auth.users(id,aud,role,email,created_at,updated_at) values
 (h,'authenticated','authenticated',h||'@example.invalid',now(),now()),(c,'authenticated','authenticated',c||'@example.invalid',now(),now()),(s,'authenticated','authenticated',s||'@example.invalid',now(),now());
 insert into public.profiles(auth_id,email,user_id,role,profile_complete,full_name,state,city) values
 (h,h||'@example.invalid',hid,'user',true,'Application host','Nasarawa','Lafia'),(c,c||'@example.invalid',cid,'user',true,'Application reviewer','Nasarawa','Lafia'),(s,s||'@example.invalid',sid,'user',true,'Other applicant','Nasarawa','Lafia');
 insert into auth.sessions(id,user_id,created_at,updated_at) values(hs,h,now(),now()),(cs,c,now(),now()),(ss,s,now(),now());
 insert into public.user_sessions(user_id,auth_id,auth_session_id,device_id,device,is_active,trust_status) values
 (hid,h,hs,'check-'||h,'Browser',true,'trusted'),(cid,c,cs,'check-'||c,'Browser',true,'trusted'),(sid,s,ss,'check-'||s,'Browser',true,'trusted');
 insert into public.workspace_role_assignments(user_id,workspace_role,scope_type) values(hid,'worker','global'),(cid,'creator','global'),(sid,'worker','global');
 insert into public.creator_elevation_grants(creator_user_id,auth_user_id,auth_session_id,action_classes,expires_at,verification_method) values(cid,c,cs::text,array['private_evidence'],now()+interval '5 minutes','password');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 receipt:=public.save_my_experience_activity(aid,0,body);
 perform pg_temp.expect((public.get_my_provider_workspace_capabilities()->>'person_id')=hid,'workspace receipt bound to person');
 perform pg_temp.expect(not (public.get_my_provider_workspace_capabilities()->>'can_manage_jobs')::boolean,'new activity-only applicant is not granted requested jobs');
 perform pg_temp.expect((public.get_my_provider_workspace_capabilities()->>'can_apply_experiences')::boolean and (public.get_my_provider_workspace_capabilities()->>'can_access_inbox')::boolean and (public.get_my_provider_workspace_capabilities()->>'can_access_earnings')::boolean,'common tools do not require requested-service approval');
 perform pg_temp.expect(receipt->'issues'='[]'::jsonb,'configured category and full activity pass validation');
 perform pg_temp.expect(public.get_experience_activity(aid,false)->>'host_user_id'=hid,'host is bound to current person');
 declare session_id uuid:=gen_random_uuid(); first_receipt jsonb; future_start timestamptz:=now()+interval '10 days';
 begin
  execute 'set local role authenticated';
  first_receipt:=public.save_my_experience_session(aid,session_id,0,1,future_start,8,250000,'NGN');
  perform pg_temp.expect(first_receipt->>'status'='draft' and (first_receipt->>'revision')::integer=1,'prepared session stays private');
  perform pg_temp.expect(public.save_my_experience_session(aid,session_id,0,1,future_start,8,250000,'NGN')=first_receipt,'lost session save response is idempotent');
  perform pg_temp.expect(jsonb_array_length(public.get_my_experience_sessions(aid))=1,'host can list prepared dates');
  perform pg_temp.expect(pg_temp.rejects('select * from public.experience_sessions'),'browser cannot bypass session RPC authority');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,1,%L,9,250000,%L)',aid,session_id,future_start,'NGN')),'session capacity cannot exceed activity maximum');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,1,%L,8,250000,%L)',aid,session_id,future_start,'USD')),'currency must match activity country');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,0,%L,8,250000,%L)',aid,session_id,future_start,'NGN')),'stale activity revision cannot prepare dates');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,1,%L,8,250000,%L)',aid,session_id,now()-interval '1 day','NGN')),'new past date rejected');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
  perform pg_temp.expect(pg_temp.rejects(format('select public.get_my_experience_sessions(%L)',aid)),'other provider cannot read prepared dates');
  perform pg_temp.expect(pg_temp.rejects(format('select public.archive_my_experience_session(%L,%L,1)',aid,session_id)),'other provider cannot archive dates');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
  first_receipt:=public.save_my_experience_session(aid,session_id,1,1,future_start,7,300000,'NGN');
  perform pg_temp.expect((first_receipt->>'revision')::integer=2,'session edit increments revision');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,1,%L,6,300000,%L)',aid,session_id,future_start,'NGN')),'conflicting stale edit rejected');
  first_receipt:=public.archive_my_experience_session(aid,session_id,2);
  perform pg_temp.expect(public.archive_my_experience_session(aid,session_id,2)=first_receipt,'archive retry is idempotent');
  perform pg_temp.expect(jsonb_array_length(public.get_my_experience_sessions(aid))=0,'archived date leaves active preparation list');
  perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,3,1,%L,7,300000,%L)',aid,session_id,future_start,'NGN')),'archived date cannot be reactivated');
  execute 'reset role';
  perform pg_temp.expect((select count(*)=3 from public.experience_session_events where experience_session_events.session_id=(first_receipt->>'id')::uuid),'three mutations retain exactly three audit snapshots');
 end;

 receipt:=public.begin_experience_activity_photo(aid,photo_id,1,9,'Orientation route and meeting area');
 perform pg_temp.expect(public.begin_experience_activity_photo(aid,photo_id,1,9,'Orientation route and meeting area')=receipt,'photo reservation retry keeps the same object');
 perform pg_temp.expect(pg_temp.rejects(format('select public.finish_experience_activity_photo(%L)',photo_id)),'missing photo object cannot become submitted');
 perform public.reserve_my_media_upload('experience-photos',receipt->>'object_path');
 insert into storage.objects(bucket_id,name,metadata,version) values('experience-photos',receipt->>'object_path','{"size":9,"mimetype":"image/jpeg"}',gen_random_uuid()::text);
 receipt:=public.finish_experience_activity_photo(photo_id);
 perform pg_temp.expect(public.finish_experience_activity_photo(photo_id)=receipt,'lost photo finish receipt is recoverable');
 perform pg_temp.expect(pg_temp.rejects(format('select public.change_experience_activity_photo(%L,2,%L,%L)',photo_id,'approved','Host cannot self-approve')),'host cannot approve an activity photo');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
 perform pg_temp.expect(not public.can_access_experience_photo_object(aid::text||'/'||photo_id::text||'.jpg'),'unrelated provider cannot read activity photo');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity_photos(%L)',aid)),'reviewer cannot browse unsent draft photos');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity(%L,true)',aid)),'Creator cannot read unsent draft');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity_history(%L)',aid)),'Creator cannot read unsent history');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 perform public.save_my_experience_session(aid,review_session,0,1,now()+interval '12 days',8,250000,'NGN');
 receipt:=public.transition_my_experience_activity(aid,1,'submit');
 perform pg_temp.expect(pg_temp.rejects(format('select public.archive_my_experience_session(%L,%L,1)',aid,review_session)),'submitted session cannot be archived');
 perform pg_temp.expect(pg_temp.rejects(format('select public.save_my_experience_session(%L,%L,1,2,%L,7,250000,%L)',aid,review_session,now()+interval '12 days','NGN')),'submitted session cannot be edited');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_review_sessions(%L,2)',aid)),'host cannot use review authority');
 receipt:=public.transition_my_experience_activity(aid,1,'submit');
 perform pg_temp.expect((select count(*)=1 from public.experience_activity_events where activity_id=aid and action='submitted'),'response-loss retry creates one submission');
 perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and a.recipient_user_id=cid and a.workspace='creator' and a.action_required and a.resolved_at is null),'submission reaches independent Creator Activity');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity(%L,false)',aid)),'another applicant cannot read activity');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity(%L,true)',aid)),'applicant cannot choose Creator read authority');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
 perform pg_temp.expect(public.get_experience_activity(aid,true)->>'status'='submitted','elevated independent Creator reads submitted activity');
 perform pg_temp.expect(jsonb_array_length(public.get_experience_activity_photos(aid))=1,'submitted application photos are reviewable');
 receipt:=public.change_experience_activity_photo(photo_id,2,'rejected','Replace the photo with a clearer view of the activity.');
 perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=photo_id::text and e.event_type='experience.photo.rejected' and a.recipient_user_id=hid and a.action_required and a.resolved_at is null),'photo replacement reaches the host as an action');
 receipt:=public.change_experience_activity_photo(photo_id,3,'approved','Real activity photo reviewed independently.');
 perform pg_temp.expect(public.change_experience_activity_photo(photo_id,3,'approved','Real activity photo reviewed independently.')=receipt,'photo decision response-loss retry is idempotent');
 perform pg_temp.expect(not exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=photo_id::text and a.action_required and a.resolved_at is null),'photo approval resolves earlier replacement actions');
 perform pg_temp.expect(pg_temp.rejects(format('select public.change_experience_activity_photo(%L,2,%L,%L)',photo_id,'rejected','Conflicting stale decision must fail.')),'conflicting photo review revision rejected');
 perform pg_temp.expect(public.get_experience_review_sessions(aid,2)->0->>'id'=review_session::text,'reviewer sees submitted dates and prices');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_review_sessions(%L,1)',aid)),'stale review revision rejected');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_review_sessions(%L,2,now(),null)',aid)),'partial review cursor rejected');
 perform pg_temp.expect(public.get_experience_activity(aid,true)->>'category_name'=(select name from public.experience_categories where code='culture_tours'),'record category label uses canonical catalog');
 perform pg_temp.expect(exists(select 1 from jsonb_array_elements(public.get_experience_activity_review_queue()) item where item->>'id'=aid::text and item->>'category_name'=(select name from public.experience_categories where code='culture_tours')),'review queue uses canonical category wording');
 declare evidence jsonb; document_id uuid; object_name text; key uuid:=gen_random_uuid();
 begin
  evidence:=public.get_experience_evidence_review(aid);
  perform pg_temp.expect(not (evidence->>'configured')::boolean and not (evidence->>'ready')::boolean,'unconfigured evidence never approves an activity');
  perform public.configure_experience_evidence_requirements(aid,0,'[{"code":"venue_permission","label":"Venue permission","instructions":"Provide permission for the proposed activity at this venue.","requires_expiry":true}]','Review the actual venue permission and its valid dates for this activity.');
  perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and e.event_type='experience.evidence.required' and a.recipient_user_id=hid and a.workspace='worker'),'requirements reach host Activity');
  perform pg_temp.expect(pg_temp.rejects(format('select public.configure_experience_evidence_requirements(%L,0,%L,%L)',aid,'[]','A stale requirements change must fail.')),'stale requirements revision rejected');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
  evidence:=public.begin_experience_evidence_upload(aid,'venue_permission',key,'application/pdf',9,'permission.pdf');
  document_id:=(evidence->>'id')::uuid;object_name:=evidence->>'object_path';
  perform pg_temp.expect(public.begin_experience_evidence_upload(aid,'venue_permission',key,'application/pdf',9,'permission.pdf')=evidence,'upload reservation retry preserves exact version');
  perform pg_temp.expect(pg_temp.rejects(format('select public.finish_experience_evidence_upload(%L)',document_id)),'missing storage object cannot become submitted evidence');
  perform public.reserve_my_media_upload('experience-evidence',object_name);
  insert into storage.objects(bucket_id,name,metadata,version) values('experience-evidence',object_name,'{"size":9,"mimetype":"application/pdf"}',gen_random_uuid()::text);
  evidence:=public.finish_experience_evidence_upload(document_id);
  perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=document_id::text and e.event_type='experience.evidence.submitted' and a.recipient_user_id=cid and a.workspace='creator' and a.action_required and a.resolved_at is null),'evidence reaches independent Creator review');
  perform pg_temp.expect(evidence->>'status'='submitted','confirmed storage metadata permits submission');
  perform pg_temp.expect(pg_temp.rejects(format('select public.review_experience_evidence(%L,%L,%L,now()+interval ''1 day'')',document_id,'approved','Host must not self-approve.')),'host self-review rejected');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'session_id',ss,'role','authenticated')::text,true);
  perform pg_temp.expect(not public.can_access_experience_evidence_object(object_name),'unrelated provider cannot read private evidence');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
  perform pg_temp.expect(pg_temp.rejects(format('select public.review_experience_evidence(%L,%L,%L)',document_id,'approved','Expiry must be confirmed.')),'required expiry cannot be omitted');
  perform public.review_experience_evidence(document_id,'approved','Venue permission reviewed for the proposed activity.',now()+interval '1 day');
  perform pg_temp.expect(not exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=document_id::text and e.event_type='experience.evidence.submitted' and a.resolved_at is null),'review resolves submission actions');
  perform pg_temp.expect((public.get_experience_evidence_review(aid)->>'ready')::boolean,'current independently approved evidence becomes ready');
 end;
 -- Exercise approval against the same prepared application in a subtransaction,
 -- then roll back only this branch so correction/withdrawal tests remain valid.
 begin
  receipt:=public.get_experience_approval_readiness(aid,2);
  perform pg_temp.expect(not (receipt->>'can_approve')::boolean and not (receipt->'checks'->>'identity')::boolean,'missing current account identity blocks activity approval');
  perform pg_temp.expect(pg_temp.rejects(format('select public.approve_experience_activity(%L,2,%L)',aid,'Activity evidence, photos and dated sessions reviewed.')),'approval cannot bypass missing identity');
  -- Synthetic passed identity is fixture setup, not a live provider verification.
  insert into public.worker_identity_checks(worker_id,account_role,status,captured_at,consent_at,attempt_count,challenge_result)
   values(hid,'worker','passed',now(),now(),1,'{"contract_fixture":true}');
  receipt:=public.get_experience_approval_readiness(aid,2);
  perform pg_temp.expect((receipt->>'can_approve')::boolean,'all required checks produce approval readiness');
  -- Later market or data changes cannot keep an obsolete session approvable.
  update public.experience_sessions set currency='USD' where activity_id=aid;
  perform pg_temp.expect(not (public.get_experience_approval_readiness(aid,2)->'checks'->>'sessions')::boolean,'stale country currency blocks session readiness');
  perform pg_temp.expect(pg_temp.rejects(format('select public.approve_experience_activity(%L,2,%L)',aid,'Activity evidence, photos and dated sessions reviewed.')),'approval rechecks current currency on the server');
  update public.experience_sessions set currency='NGN',capacity=9 where activity_id=aid;
  perform pg_temp.expect(not (public.get_experience_approval_readiness(aid,2)->'checks'->>'sessions')::boolean,'capacity above the reviewed group size blocks approval');
  update public.experience_sessions set capacity=8,timezone='UTC' where activity_id=aid;
  perform pg_temp.expect(not (public.get_experience_approval_readiness(aid,2)->'checks'->>'sessions')::boolean,'session timezone must match the reviewed activity');
  update public.experience_sessions set timezone='Africa/Lagos',ends_at=starts_at+interval '2 hours' where activity_id=aid;
  perform pg_temp.expect(not (public.get_experience_approval_readiness(aid,2)->'checks'->>'sessions')::boolean,'session duration must match the reviewed activity');
  update public.experience_sessions set ends_at=starts_at+interval '1 hour' where activity_id=aid;
  perform pg_temp.expect((public.get_experience_approval_readiness(aid,2)->>'can_approve')::boolean,'restoring current session terms restores readiness');
  perform pg_temp.expect(pg_temp.rejects(format('select public.approve_experience_activity(%L,1,%L)',aid,'Activity evidence, photos and dated sessions reviewed.')),'stale activity approval rejected');
  receipt:=public.approve_experience_activity(aid,2,'Activity evidence, photos and dated sessions reviewed.');
  perform pg_temp.expect(receipt->>'status'='approved' and (receipt->>'approved_from_revision')::integer=2 and (receipt->>'revision')::integer=3,'approval is bound to the reviewed application revision');
  perform pg_temp.expect(public.approve_experience_activity(aid,2,'Activity evidence, photos and dated sessions reviewed.')=receipt,'lost approval response replays the original result');
  perform pg_temp.expect((select count(*)=1 from public.experience_activity_events where activity_id=aid and action='approved'),'approval retry writes one decision event');
  perform pg_temp.expect(public.get_experience_activity(aid,true)->>'status'='approved','reviewer can reopen the approved record');
  perform pg_temp.expect(not exists(select 1 from jsonb_array_elements(public.get_experience_activity_review_queue()) row where row->>'id'=aid::text),'approved activity leaves the pending review queue');
  perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and e.event_type='experience.application.approved' and a.recipient_user_id=hid and a.workspace='worker'),'approval reaches host Activity');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
  perform pg_temp.expect(not (public.get_experience_evidence_review(aid)->>'can_submit')::boolean,'approved evidence is read-only until revision');
  perform pg_temp.expect(pg_temp.rejects(format('select public.archive_my_experience_session(%L,%L,1)',aid,review_session)),'approved dated sessions cannot be changed silently');
  perform pg_temp.expect(pg_temp.rejects(format('select public.begin_experience_activity_photo(%L,%L,3,9,%L)',aid,gen_random_uuid(),'An unreviewed additional photo')),'approved photos require a new activity revision');
  receipt:=public.transition_my_experience_activity(aid,3,'withdraw');
  perform pg_temp.expect(receipt->>'status'='withdrawn','host can revise an approved activity');
  receipt:=public.transition_my_experience_activity(aid,4,'submit');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
  receipt:=public.get_experience_approval_readiness(aid,5);
  perform pg_temp.expect(not (receipt->>'can_approve')::boolean and not (receipt->'checks'->>'sessions')::boolean,'resubmission cannot reuse obsolete session revisions for approval');
  raise exception using errcode='ZP001',message='Rollback approval branch only';
 exception when sqlstate 'ZP001' then null;
 end;
 receipt:=public.request_experience_activity_changes(aid,2,'changes_required','Clarify the route, meeting point and accessible assistance arrangements.');
 perform pg_temp.expect(not exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and e.event_type='experience.application.submitted' and a.resolved_at is null),'decision resolves prior submission actions');
 perform pg_temp.expect(exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and a.recipient_user_id=hid and a.workspace='worker' and a.action_required and a.resolved_at is null),'correction reaches host as actionable Activity');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 receipt:=public.save_my_experience_activity(aid,3,body||'{"meeting_area":"Public main gate by the information desk"}'::jsonb);
 perform pg_temp.expect(not (public.get_experience_activity_photos(aid)->0->>'context_current')::boolean,'activity changes invalidate previous photo approval context');
 receipt:=public.change_experience_activity_photo(photo_id,4,'refresh_context');
 perform pg_temp.expect(receipt->>'status'='submitted' and receipt->>'reviewed_by' is null,'reusing photo for revised activity clears the previous approval');
 perform pg_temp.expect(not (public.get_experience_evidence_review(aid)->>'ready')::boolean,'changed activity invalidates old evidence context');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity(%L,true)',aid)),'new unsent revision is private even after earlier submission');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 receipt:=public.transition_my_experience_activity(aid,4,'submit');
 receipt:=public.transition_my_experience_activity(aid,5,'withdraw');
 perform pg_temp.expect(not exists(select 1 from public.activity_event_audiences a join public.activity_events e using(activity_event_id) where e.subject_id=aid::text and a.action_required and a.resolved_at is null),'withdrawal resolves pending review and correction actions');

 -- Canonical Experience commission: role/device authority, optimistic versions and retry.
 perform pg_temp.expect(pg_temp.rejects('select public.creator_get_experience_commission()'),'host cannot read Creator commission controls');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'session_id',cs,'role','authenticated')::text,true);
 declare ep integer; eg uuid; commission jsonb;
 begin
  update public.creator_elevation_grants set action_classes=array['private_evidence','policy_publish'] where creator_user_id=cid returning creator_elevation_id into eg;
  commission:=public.creator_get_experience_commission();ep:=coalesce((commission->'policy'->>'version')::integer,0);
  commission:=public.creator_publish_experience_commission(eg,ep,0,'Contract verification only; rolled back.');
  perform pg_temp.expect((commission->'policy'->>'version')::integer=ep+1 and (commission->'policy'->'value'->>'percent')::numeric=0,'published explicit zero percentage and new version confirmed');
  commission:=public.creator_publish_experience_commission(eg,ep,0,'Contract verification only; rolled back.');
  perform pg_temp.expect((commission->'policy'->>'version')::integer=ep+1,'retry does not create another policy version');
  perform pg_temp.expect(pg_temp.rejects(format('select public.creator_publish_experience_commission(%L,%s,10,%L)',eg,ep,'Stale change must be refused')),'stale update rejected');
  perform pg_temp.expect(pg_temp.rejects(format('select public.creator_publish_experience_commission(%L,%s,51,%L)',eg,ep+1,'Invalid rate must be refused')),'invalid percentage rejected');
  update public.user_sessions set is_active=false,trust_status='rejected' where user_id=cid;
  perform pg_temp.expect(pg_temp.rejects('select public.creator_get_experience_commission()'),'revoked Creator device rejected');
 end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'session_id',hs,'role','authenticated')::text,true);
 update public.user_sessions set is_active=false,trust_status='rejected' where user_id=hid;
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity(%L,false)',aid)),'revoked device cannot read application');
 perform pg_temp.expect(pg_temp.rejects('select public.get_my_provider_workspace_capabilities()'),'revoked device cannot obtain capabilities');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_my_experience_sessions(%L)',aid)),'revoked device cannot read sessions');
 perform pg_temp.expect(pg_temp.rejects(format('select public.get_experience_activity_photos(%L)',aid)),'revoked device cannot read private photos');
end $$;
rollback;
select 'Application lifecycle, Activity delivery, retry, draft privacy and role/device rejection checks passed; all fixtures rolled back' as result;
